begin;
create temporary table live_checks(label text);
grant select,insert on live_checks to anon,authenticated;
create function pg_temp.ok_live(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED: %',label;end if;insert into live_checks values(label);end $$;
create function pg_temp.denied_live(command text,label text) returns void language plpgsql as $$declare denied boolean:=false;begin begin execute command;exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok_live(denied,label);end $$;
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) values
 ('73000000-0000-4000-8000-000000000001','live-v1@example.invalid','{"role":"vendor","name":"Live Vendor"}',now()),
 ('73000000-0000-4000-8000-000000000002','live-c1@example.invalid','{"role":"customer","name":"Live Customer"}',now()),
 ('73000000-0000-4000-8000-000000000003','live-c2@example.invalid','{"role":"customer","name":"Other Customer"}',now()),
 ('73000000-0000-4000-8000-000000000004','live-owner@example.invalid','{"role":"admin"}',now());
insert into public.admins(id,name,access_level) values('73000000-0000-4000-8000-000000000004','Live Owner','owner');
select eventra_security.touch_app_revision('public','test_public');
select eventra_security.touch_app_revision('user:73000000-0000-4000-8000-000000000002','test_private');
select eventra_security.touch_app_revision('admin','test_admin');
set local role anon;
select set_config('request.jwt.claims','{}',true);
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where dataset='test_public'),'guest reads public revision');
select pg_temp.ok_live(not exists(select 1 from public.app_data_revisions where dataset in ('test_private','test_admin')),'guest cannot read user/admin revisions');
select pg_temp.denied_live($q$insert into public.app_data_revisions values('public','fake',1,now())$q$,'guest cannot spoof updates');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"73000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where dataset='test_private'),'customer sees own revision');
select pg_temp.ok_live(not exists(select 1 from public.app_data_revisions where dataset='test_admin'),'customer cannot observe admin revisions');
select pg_temp.denied_live($q$update public.app_data_revisions set version=999$q$,'customer cannot write revision counters');
select pg_temp.denied_live('delete from public.app_data_revisions','customer cannot delete counters');
select pg_temp.denied_live($q$select eventra_security.touch_app_revision('public','fake')$q$,'private publisher cannot be called by app');
select set_config('request.jwt.claims','{"sub":"73000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.ok_live(not exists(select 1 from public.app_data_revisions where dataset='test_private'),'second customer cannot see first customer event');
select set_config('request.jwt.claims','{"sub":"73000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok_live(not exists(select 1 from public.app_data_revisions where dataset='test_admin'),'owner admin feed requires MFA');
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000004'),'owner can receive own access-revocation hints before MFA');
select set_config('request.jwt.claims','{"sub":"73000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where dataset='test_admin'),'MFA owner can observe admin feed');
reset role;
create temporary table prior_live(version bigint);
insert into prior_live select version from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000002' and dataset='customers';
update public.customers set name='Changed live customer' where id='73000000-0000-4000-8000-000000000002';
select pg_temp.ok_live((select version>(select version from prior_live) from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000002' and dataset='customers'),'profile update increments own revision');
select pg_temp.ok_live(not exists(select 1 from public.app_data_revisions where audience='public' and dataset='customers'),'private profile changes do not become public');
truncate prior_live;
insert into prior_live select version from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000002' and dataset='customers';
update public.customers set name=name where id='73000000-0000-4000-8000-000000000002';
select pg_temp.ok_live((select version=(select version from prior_live) from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000002' and dataset='customers'),'no-op writes do not produce refresh loops');
insert into public.category_nodes(id,name,slug) values('73000000-0000-4000-8000-000000000010','Live category','live-category-test');
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='public' and dataset='category_nodes'),'catalogue changes emit public hint');
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='admin' and dataset='category_nodes'),'catalogue changes emit admin hint');
insert into public.businesses(id,vendor_id,name,primary_category_id) values('73000000-0000-4000-8000-000000000020','73000000-0000-4000-8000-000000000001','Live Business','73000000-0000-4000-8000-000000000010');
insert into public.business_category_nodes(business_id,category_node_id) values('73000000-0000-4000-8000-000000000020','73000000-0000-4000-8000-000000000010');
insert into public.services(id,vendor_id,business_id,category_node_id,name,slug,price) values('73000000-0000-4000-8000-000000000030','73000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000020','73000000-0000-4000-8000-000000000010','Live Service','live-revision-test-service',100);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"73000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.customer_service_signal('73000000-0000-4000-8000-000000000030','view');
reset role;
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000002' and dataset='recommendations'),'personalization update reaches its customer');
select pg_temp.ok_live(not exists(select 1 from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000001' and dataset='recommendations'),'private interests do not notify the vendor');

insert into eventra_admin.team_permissions(admin_id,module,can_write) values('73000000-0000-4000-8000-000000000004','support_faqs',true);
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000004' and dataset='team_permissions'),'permission changes notify affected staff identity');
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='public' and dataset='vendors'),'public vendor catalogue revision exists');
update auth.users set banned_until=now()+interval '1 day' where id='73000000-0000-4000-8000-000000000001';
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='public' and dataset='services'),'vendor suspension refreshes public service availability');
select pg_temp.ok_live(exists(select 1 from public.app_data_revisions where audience='user:73000000-0000-4000-8000-000000000001' and dataset='access'),'suspension sends own access signal');
select pg_temp.ok_live((select array_agg(column_name::text order by ordinal_position)=array['audience','dataset','version','changed_at'] from information_schema.columns where table_schema='public' and table_name='app_data_revisions'),'event schema contains no record payloads or PII fields');
select pg_temp.ok_live(exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='app_data_revisions'),'revision table is published');
select pg_temp.ok_live(not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename in ('customers','support_messages','admins')),'private source tables were not added to publication');
select pg_temp.ok_live((select relrowsecurity from pg_class where oid='public.app_data_revisions'::regclass),'revision RLS enabled');
select count(*) as passed_app_realtime_checks from live_checks;
rollback;
